solution:
fn middle_element(v: &Vec[Int]) -> Int
  requires: v.len() > 0;
  requires: v.len() % 2 == 1;
{
  let mid = v.len() / 2;
  return v[mid];
}

fn main() -> Int {
  let data = Vec[Int]();
  data.push(10); data.push(20); data.push(30);
  return middle_element(&data);
}
